import{_ as r,o as a,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"گورننس کا فریم ورک اور طاقتوں کا توازن","description":"","frontmatter":{},"headers":[],"relativePath":"ur/49-治理框架与权力制衡.md","filePath":"ur/49-治理框架与权力制衡.md"}'),o={name:"ur/49-治理框架与权力制衡.md"};function i(e,t,n,h,s,u){return a(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="گورننس-کا-فریم-ورک-اور-طاقتوں-کا-توازن" tabindex="-1">گورننس کا فریم ورک اور طاقتوں کا توازن <a class="header-anchor" href="#گورننس-کا-فریم-ورک-اور-طاقتوں-کا-توازن" aria-label="Permalink to &quot;گورننس کا فریم ورک اور طاقتوں کا توازن&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>49</td></tr><tr><td>ماڈیول</td><td>قانونی نظام اور گورننس کا فریم ورک</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>تین طاقتوں کی تقسیم، طاقتوں کا توازن، اینکر کونسل، نگرانی کمیٹی، سمبیوسس گورننس</td></tr></tbody></table><h2 id="أولاً-گورننس-کے-فریم-ورک-کا-عمومی-ڈیزائن" tabindex="-1">أولاً. گورننس کے فریم ورک کا عمومی ڈیزائن <a class="header-anchor" href="#أولاً-گورننس-کے-فریم-ورک-کا-عمومی-ڈیزائن" aria-label="Permalink to &quot;أولاً. گورننس کے فریم ورک کا عمومی ڈیزائن&quot;">​</a></h2><p>اینکر سمبیوسس تہذیب کے گورننس کا فریم ورک 《سمبیوسس آئین》 کو بنیادی بنیاد کے طور پر لیتا ہے، اور &quot;تین طاقتوں کی تقسیم، چار طاقتوں کا توازن&quot; کے گورننس کے ڈھانچے کو لاگو کرتا ہے۔ تین طاقتوں سے مراد قانون سازی کی طاقت، انتظامی طاقت، اور عدلیہ کی طاقت ہے، جو بالترتیب اینکر کونسل، سمبیوسس ایگزیکٹو کمیٹی، اور سمبیوسس عدالت کے ذریعے چلائی جاتی ہیں۔ چوتھی طاقت نگرانی کی طاقت ہے، جو آزاد اینکر نگرانی کمیٹی کے ذریعے چلائی جاتی ہے، اور تین طاقتوں پر مکمل نگرانی کرتی ہے۔ اس ڈھانچے کا بنیادی مقصد طاقت کے ارتکاز اور غلط استعمال کو روکنا ہے، اور ادارہ جاتی سطح سے لوٹ مار کے گورننس کی جڑ کو ختم کرنا ہے۔</p><p>گورننس کے فریم ورک کا ڈیزائن درج ذیل اصولوں کی پیروی کرتا ہے:</p><table tabindex="0"><thead><tr><th>اصول</th><th>مواد</th></tr></thead><tbody><tr><td>طاقتوں کی تقسیم کا اصول</td><td>قانون سازی، انتظامیہ، عدلیہ تین طاقتیں بالترتیب مختلف اداروں کے ذریعے چلائی جاتی ہیں، اور ایک ساتھ نہیں لی جا سکتیں</td></tr><tr><td>طاقتوں کے توازن کا اصول</td><td>ہر طاقت کا ادارہ باہمی طور پر روک ٹوک اور نگرانی کرتا ہے، اور کسی ایک فریق کی طاقت کا ضرورت سے زیادہ بڑھنا روکتا ہے</td></tr><tr><td>تمام نسلوں کی شرکت کا اصول</td><td>گورننس کے اداروں کی تشکیل میں تمام نسلوں کی نمائندگی ظاہر ہونی چاہیے، اور یقینی بنانا چاہیے کہ ہر نسل عوامی معاملات میں حصہ لے سکے</td></tr><tr><td>جمہوری مرتکز اصول</td><td>اہم فیصلے مکمل جمہوری بحث کے بعد مرتکز طور پر طے کیے جاتے ہیں، اور کارکردگی اور جمہوریت دونوں کو مدنظر رکھا جاتا ہے</td></tr><tr><td>بنیادی خود مختاری کا اصول</td><td>بنیادی معاملات بنیادی خود مختاری تنظیم کے ذریعے چلائے جاتے ہیں، اور اعلیٰ ادارے ضرورت سے زیادہ مداخلت نہیں کر سکتے</td></tr><tr><td>شفاف گورننس کا اصول</td><td>گورننس کا عمل اور فیصلے کی معلومات قانون کے مطابق شائع کی جاتی ہیں، اور عوامی نگرانی قبول کرتی ہیں</td></tr></tbody></table><h2 id="ثانياً-قانون-سازی-کی-طاقت-اینکر-کونسل" tabindex="-1">ثانياً. قانون سازی کی طاقت: اینکر کونسل <a class="header-anchor" href="#ثانياً-قانون-سازی-کی-طاقت-اینکر-کونسل" aria-label="Permalink to &quot;ثانياً. قانون سازی کی طاقت: اینکر کونسل&quot;">​</a></h2><p>اینکر کونسل اینکر سمبیوسس تہذیب کا اعلیٰ ترین طاقت کا ادارہ ہے، اور قانون سازی کی طاقت اور اہم معاملات کے فیصلے کی طاقت کا استعمال کرتا ہے۔</p><h3 id="_1-تشکیل-اور-پیدائش" tabindex="-1">(1) تشکیل اور پیدائش <a class="header-anchor" href="#_1-تشکیل-اور-پیدائش" aria-label="Permalink to &quot;(1) تشکیل اور پیدائش&quot;">​</a></h3><ul><li><strong>نمائندوں کی تشکیل</strong>: اینکر کونسل تمام نسلوں کے نمائندوں پر مشتمل ہے، اور انسانی نسل کے نمائندے کل تعداد کے 30 فیصد سے زیادہ نہیں ہیں، اور باقی نشستیں ہر نسل کی آبادی کے سائز اور شراکت کی ڈگری کے مطابق تقسیم کی جاتی ہیں۔</li><li><strong>نمائندوں کی مدت</strong>: کونسل کے نمائندوں کی مدت پانچ سال ہے، اور وہ دوبارہ منتخب ہو سکتے ہیں، لیکن دوبارہ انتخاب تین مدت سے زیادہ نہیں ہو سکتا۔</li><li><strong>انتخاب کا طریقہ</strong>: نمائندے ہر نسل کے اندرونی جمہوری انتخاب کے ذریعے منتخب ہوتے ہیں، اور انتخاب کا عمل کھلا اور شفاف ہوتا ہے، اور نگرانی قبول کرتا ہے۔</li><li><strong>مستقل ادارہ</strong>: کونسل کی اجتماعت کے دوران، مستقل کمیٹی کچھ طاقتیں استعمال کرتی ہے، اور مستقل کمیٹی کے ارکان نمائندوں میں سے منتخب ہوتے ہیں۔</li></ul><h3 id="_2-اختیارات-کا-دائرہ" tabindex="-1">(2) اختیارات کا دائرہ <a class="header-anchor" href="#_2-اختیارات-کا-دائرہ" aria-label="Permalink to &quot;(2) اختیارات کا دائرہ&quot;">​</a></h3><ol><li><strong>قانون سازی کی طاقت</strong>: آئین، بنیادی قانون، اور دیگر اہم قوانین کی تشکیل اور ترمیم کرنا۔</li><li><strong>اہم معاملات کے فیصلے کی طاقت</strong>: تہذیب کی ترقی کے منصوبے، سالانہ بجٹ، جنگ اور امن،位面 کی ترقی، اور دیگر اہم معاملات کا فیصلہ کرنا۔</li><li><strong>تقرری اور برخاستگی کی طاقت</strong>: سمبیوسس ایگزیکٹو کمیٹی کے صدر، سمبیوسس عدالت کے صدر جج، اینکر نگرانی کمیٹی کے ڈائریکٹر، اور دیگر اہم افسران کا انتخاب اور برخاستگی کرنا۔</li><li><strong>نگرانی کی طاقت</strong>: سمبیوسس ایگزیکٹو کمیٹی اور سمبیوسس عدالت کے کام کی نگرانی کرنا، اور کام کی رپورٹ سننا اور غور کرنا۔</li><li><strong>آئین کی ترمیم کی طاقت</strong>: آئین کی ترمیم کے لیے دو تہائی سے زیادہ اکثریت کی منظوری اور عوامی ریفرنڈم درکار ہے۔</li></ol><h3 id="_3-议事-کے-اصول" tabindex="-1">(3)议事 کے اصول <a class="header-anchor" href="#_3-议事-کے-اصول" aria-label="Permalink to &quot;(3)议事 کے اصول&quot;">​</a></h3><ul><li>کونسل ہر سال ایک بار مکمل اجلاس کرتا ہے، اور ضرورت پڑنے پر غیر معمولی اجلاس بلایا جا سکتا ہے۔</li><li>قانون کے مسودے پر غور کرنے میں &quot;تین بار پڑھنے&quot; کا نظام لاگو ہوتا ہے: پہلی بار پڑھنے میں قانون سازی کی ضرورت پر غور کیا جاتا ہے، دوسری بار پڑھنے میں آرٹیکل کے مواد پر غور کیا جاتا ہے، اور تیسری بار پڑھنے میں منظوری کے لیے ووٹنگ کی جاتی ہے۔</li><li>ووٹنگ میں ایک شخص ایک ووٹ ہوتا ہے، اور عام قانون سادہ اکثریت سے منظور ہوتے ہیں، اور آئین کی ترمیم دو تہائی سے زیادہ اکثریت سے منظور ہوتی ہے۔ -议事 کا عمل کھلے طور پر ہوتا ہے، اور عوام کو سامعین کے طور پر شرکت اور میڈیا کی رپورٹنگ کی اجازت ہے۔</li></ul><h2 id="ثالثاً-انتظامی-طاقت-سمبیوسس-ایگزیکٹو-کمیٹی" tabindex="-1">ثالثاً. انتظامی طاقت: سمبیوسس ایگزیکٹو کمیٹی <a class="header-anchor" href="#ثالثاً-انتظامی-طاقت-سمبیوسس-ایگزیکٹو-کمیٹی" aria-label="Permalink to &quot;ثالثاً. انتظامی طاقت: سمبیوسس ایگزیکٹو کمیٹی&quot;">​</a></h2><p>سمبیوسس ایگزیکٹو کمیٹی اینکر سمبیوسس تہذیب کا اعلیٰ ترین انتظامی ادارہ ہے، اور آئین اور قانون کے نفاذ، اور روزمرہ گورننس کے لیے ذمہ دار ہے۔</p><h3 id="_1-تشکیل-اور-پیدائش-1" tabindex="-1">(1) تشکیل اور پیدائش <a class="header-anchor" href="#_1-تشکیل-اور-پیدائش-1" aria-label="Permalink to &quot;(1) تشکیل اور پیدائش&quot;">​</a></h3><ul><li><strong>صدارت کا نظام</strong>: سمبیوسس ایگزیکٹو کمیٹی صدر کی ذمہ داری کا نظام لاگو کرتی ہے، اور صدر انتظامی سربراہ ہے، جو اینکر کونسل کے ذریعے منتخب ہوتا ہے، اور اس کی مدت پانچ سال ہے، اور ایک بار دوبارہ منتخب ہو سکتا ہے۔</li><li><strong>ارکان کی تشکیل</strong>: کمیٹی صدر، نائب صدر، اور ہر محکمے کے سربراہ پر مشتمل ہے، اور ہر محکمے کے سربراہ صدر کے ذریعے نامزد کیے جاتے ہیں اور کونسل کے ذریعے تقرر کیے جاتے ہیں۔</li><li><strong>غیر ملکی نسل کا کوٹہ</strong>: کمیٹی کے ارکان میں غیر ملکی نسل کا تناسب 40 فیصد سے کم نہیں ہے، اور یقینی بناتا ہے کہ انتظامی فیصلے میں ہر نسل کے مفادات مدنظر رکھے جائیں۔</li></ul><h3 id="_2-اختیارات-کا-دائرہ-1" tabindex="-1">(2) اختیارات کا دائرہ <a class="header-anchor" href="#_2-اختیارات-کا-دائرہ-1" aria-label="Permalink to &quot;(2) اختیارات کا دائرہ&quot;">​</a></h3><ol><li><strong>انتظامی قانون سازی کی طاقت</strong>: آئین اور قانون کی بنیاد پر انتظامی ضوابط، قواعد، اور پالیسیاں تیار کرنا۔</li><li><strong>انتظامی انتظام کی طاقت</strong>: معیشت، تعلیم، سائنس، ثقافت، صحت، کھیل، ماحول وغیرہ کے مختلف انتظامی کاموں کی قیادت اور انتظام کرنا۔</li><li><strong>افرادی انتظام کی طاقت</strong>: قانون کی دفعات کے مطابق انتظامی اہلکاروں کی تقرری، تربیت، تشخیص، اور انعام و سزا۔</li><li><strong>سفارتی طاقت</strong>: سمبیوسس تہذیب کی نمائندگی کرتے ہوئے بین位面 سفارتی سرگرمیاں چلانا، اور معاہدے اور معاہدے پر دستخط کرنا۔</li><li><strong>ہنگامی حالت کی طاقت</strong>: سنگین غیر متوقع واقعات پیش آنے پر، قانون کے مطابق ہنگامی حالت کا اعلان کر سکتا ہے اور ہنگامی اقدامات اٹھا سکتا ہے، لیکن مقررہ مدت میں کونسل کی منظوری کے لیے پیش کرنا ہوگا۔</li></ol><h3 id="_3-انتظامی-محکموں-کی-ترتیب" tabindex="-1">(3) انتظامی محکموں کی ترتیب <a class="header-anchor" href="#_3-انتظامی-محکموں-کی-ترتیب" aria-label="Permalink to &quot;(3) انتظامی محکموں کی ترتیب&quot;">​</a></h3><table tabindex="0"><thead><tr><th>محکمہ</th><th>بنیادی کام</th></tr></thead><tbody><tr><td>سمبیوسس ترقی محکمہ</td><td>تہذیب کی ترقی کے منصوبے تیار کرنا، اور مختلف شعبوں کی ترقی کو مربوط کرنا</td></tr><tr><td>وسائل کا انتظام محکمہ</td><td>سادھنہ وسائل اور عوامی وسائل کا انتظام کرنا، اور مشترکہ پیداوار معاہدے کے نظام کو نافذ کرنا</td></tr><tr><td>تعلیم و ثقافت محکمہ</td><td>تعلیمی امور اور ثقافتی معاملات کا انتظام کرنا</td></tr><tr><td>صحت و علاج محکمہ</td><td>صحت و علاج کے امور اور عوامی صحت کا انتظام کرنا</td></tr><tr><td>ماحولیات و ماحول محکمہ</td><td>ماحولیاتی تحفظ اور ماحولیاتی تعمیر کا انتظام کرنا</td></tr><tr><td>位面 امور محکمہ</td><td>位面 کی ترقی اور بین位面 امور کا انتظام کرنا</td></tr><tr><td>تمام نسلوں کے امور محکمہ</td><td>تمام نسلوں کے تعلقات کو مربوط کرنا، اور غیر ملکی نسل کے امور کو سنبھالنا</td></tr><tr><td>مالیات و معیشت محکمہ</td><td>مالی بجٹ اور معاشی آپریشن کا انتظام کرنا</td></tr><tr><td>سلامتی محکمہ</td><td>عوامی سلامتی اور تہذیب کی سلامتی کی حفاظت کرنا</td></tr></tbody></table><h2 id="رابعاً-عدلیہ-کی-طاقت-سمبیوسس-عدالت" tabindex="-1">رابعاً. عدلیہ کی طاقت: سمبیوسس عدالت <a class="header-anchor" href="#رابعاً-عدلیہ-کی-طاقت-سمبیوسس-عدالت" aria-label="Permalink to &quot;رابعاً. عدلیہ کی طاقت: سمبیوسس عدالت&quot;">​</a></h2><p>سمبیوسس عدالت اینکر سمبیوسس تہذیب کا اعلیٰ ترین عدلیہ ادارہ ہے، اور آزادانہ طور پر انصاف کی طاقت کا استعمال کرتی ہے۔ اس کی تنظیمی نظام، مقدمے کا عمل، اور غیر آئینی جائزے کا نظام 《48-عدلیہ کا نظام اور فیصلے کا طریقہ کار》 میں تفصیل سے بیان کیا گیا ہے۔</p><p>طاقتوں کے توازن کے فریم ورک میں، عدلیہ کی طاقت کا قانون سازی کی طاقت اور انتظامی طاقت پر روک ٹوک اس میں ظاہر ہوتی ہے:</p><ol><li><strong>غیر آئینی جائزے کی طاقت</strong>: سمبیوسس عدالت کی طاقت ہے کہ وہ آئین کی خلاف ورزی کرنے والے قوانین اور انتظامی ضوابط کو غیر موثر قرار دے۔</li><li><strong>انتظامی انصاف کی طاقت</strong>: عدالت کی طاقت ہے کہ وہ انتظامی مقدمات کی سماعت کرے، اور انتظامی عمل کی قانونی حیثیت کا جائزہ لے۔</li><li><strong>محرومیت کے انصاف کی طاقت</strong>: کونسل کے ذریعے پیش کیے گئے اعلیٰ افسران کے محرومیت کے مقدمات سمبیوسس عدالت کے ذریعے سماعت کیے جاتے ہیں۔</li></ol><p>اسی وقت، عدلیہ کی طاقت بھی قانون سازی کی طاقت اور انتظامی طاقت کے ذریعے روک ٹوک کی جاتی ہے: جج کونسل کے ذریعے تقرر کیے جاتے ہیں، عدلیہ کا بجٹ انتظامی محکمہ کے ذریعے تیار کیا جاتا ہے (لیکن کونسل کی منظوری درکار ہے اور انتظامی ادارے کے ذریعے کم نہیں کیا جا سکتا)، اور اینکر نگرانی کمیٹی عدلیہ کی سرگرمیوں کی نگرانی کرتی ہے۔</p><h2 id="خامساً-نگرانی-کی-طاقت-اینکر-نگرانی-کمیٹی" tabindex="-1">خامساً. نگرانی کی طاقت: اینکر نگرانی کمیٹی <a class="header-anchor" href="#خامساً-نگرانی-کی-طاقت-اینکر-نگرانی-کمیٹی" aria-label="Permalink to &quot;خامساً. نگرانی کی طاقت: اینکر نگرانی کمیٹی&quot;">​</a></h2><p>اینکر نگرانی کمیٹی ایک آزاد نگرانی ادارہ ہے، اور چوتھی طاقت - نگرانی کی طاقت کا استعمال کرتی ہے، اور تمام طاقت کے اداروں پر مکمل نگرانی کرتی ہے۔</p><h3 id="_1-تشکیل-اور-پیدائش-2" tabindex="-1">(1) تشکیل اور پیدائش <a class="header-anchor" href="#_1-تشکیل-اور-پیدائش-2" aria-label="Permalink to &quot;(1) تشکیل اور پیدائش&quot;">​</a></h3><ul><li><strong>ڈائریکٹر کی ذمہ داری کا نظام</strong>: نگرانی کمیٹی ڈائریکٹر کی ذمہ داری کا نظام لاگو کرتی ہے، اور ڈائریکٹر اینکر کونسل کے ذریعے منتخب ہوتا ہے، اور اس کی مدت پانچ سال ہے، اور دوبارہ منتخب نہیں ہو سکتا۔</li><li><strong>ارکان کی تشکیل</strong>: کمیٹی کے ارکان تمام نسلوں کے نمائندے، قانونی ماہرین، اور عوامی نمائندے پر مشتمل ہیں، اور ان میں کل وقتی ارکان نصف سے کم نہیں ہیں۔</li><li><strong>آزادی کی تحفظ</strong>: نگرانی کمیٹی کا بجٹ آزادانہ طور پر الگ کیا جاتا ہے، اور ارکان کو قانونی وجہ کے بغیر عہدے سے ہٹایا نہیں جا سکتا، اور نگرانی کی آزادی کو یقینی بنایا جاتا ہے۔</li></ul><h3 id="_2-اختیارات-کا-دائرہ-2" tabindex="-1">(2) اختیارات کا دائرہ <a class="header-anchor" href="#_2-اختیارات-کا-دائرہ-2" aria-label="Permalink to &quot;(2) اختیارات کا دائرہ&quot;">​</a></h3><ol><li><strong>دیانتداری کی نگرانی</strong>: تمام عوامی افسران کی دیانتداری اور خود نظم و ضبط کی صورتحال کی نگرانی کرنا، اور بدعنوانی، رشوت، ذاتی فائدے کے لیے طاقت کا غلط استعمال وغیرہ کے کارروائیوں کی تحقیقات اور سزا۔</li><li><strong>کارکردگی کی نگرانی</strong>: ہر طاقت کے ادارے کی کام کی کارکردگی کی نگرانی کرنا، اور کام نہ کرنا، بے ضابطگی سے کام کرنا، سست کام کرنا وغیرہ کے کارروائیوں کی تحقیقات اور سزا۔</li><li><strong>قانون کے نفاذ کی نگرانی</strong>: قانون کے نفاذ کی صورتحال کی نگرانی کرنا، اور قانون کی پیروی نہ کرنا، قانون کو سخت طریقے سے نافذ نہ کرنا، غیر قانونی کارروائیوں کی تحقیقات نہ کرنا وغیرہ کے کارروائیوں کی تحقیقات اور سزا۔</li><li><strong>مالی نگرانی</strong>: عوامی مالیات کے استعمال کی صورتحال کی نگرانی کرنا، اور عوامی وسائل کے ضیاع، سرکاری رقم کے غلط استعمال وغیرہ کے کارروائیوں کی تحقیقات اور سزا۔</li><li><strong>لوٹ مار کے کارروائیوں کی نگرانی</strong>: خاص طور پر لوٹ مار کے کارروائیوں کی دوبارہ پیدا ہونے کی نگرانی کرنا، اور لوٹ مار کے لیے طاقت کے استعمال کے کارروائیوں کی تحقیقات اور سزا۔</li></ol><h3 id="_3-نگرانی-کے-طریقے" tabindex="-1">(3) نگرانی کے طریقے <a class="header-anchor" href="#_3-نگرانی-کے-طریقے" aria-label="Permalink to &quot;(3) نگرانی کے طریقے&quot;">​</a></h3><ul><li>روزمرہ کی نگرانی: دورہ، جانچ، آڈٹ وغیرہ کے طریقوں سے روزمرہ کی نگرانی کرنا۔</li><li>خصوصی نگرانی: مخصوص شعبے یا مخصوص مسائل کے لیے خصوصی نگرانی چلانا۔</li><li>شکایات کی وصولی: عوام کی جانب سے غیر قانونی اور غیر اخلاقی کارروائیوں کی شکایات اور شکایات وصول کرنا۔</li><li>تحقیقات اور جوابدہی: غیر قانونی اور غیر اخلاقی کارروائیوں کے شبہ میں تحقیقات کرنا، اور جوابدہی کی سفارشات پیش کرنا۔</li><li>عوامی اطلاع: باقاعدگی سے نگرانی کی صورتحال اور عام معاملات شائع کرنا، اور سماجی نگرانی قبول کرنا۔</li></ul><h2 id="سادساً-طاقتوں-کے-توازن-کا-طریقہ-کار" tabindex="-1">سادساً. طاقتوں کے توازن کا طریقہ کار <a class="header-anchor" href="#سادساً-طاقتوں-کے-توازن-کا-طریقہ-کار" aria-label="Permalink to &quot;سادساً. طاقتوں کے توازن کا طریقہ کار&quot;">​</a></h2><p>ہر طاقت کے ادارے کے درمیان توازن کے تعلقات درج ذیل جدول میں دکھائے گئے ہیں:</p><table tabindex="0"><thead><tr><th>توازن کا تعلق</th><th>توازن کا طریقہ</th></tr></thead><tbody><tr><td>قانون سازی کی طاقت انتظامی طاقت کو روکتی ہے</td><td>کونسل کی طاقت ہے کہ وہ انتظامی صدر کو برخاست کرے، انتظامی تجاویز کو مسترد کرے، بجٹ کی منظوری دے</td></tr><tr><td>قانون سازی کی طاقت عدلیہ کی طاقت کو روکتی ہے</td><td>کونسل کی طاقت ہے کہ وہ جج تقرر کرے، عدالت کے تنظیمی قانون میں ترمیم کرے، جج کے خلاف محرومیت کا مقدمہ دائر کرے</td></tr><tr><td>انتظامی طاقت قانون سازی کی طاقت کو روکتی ہے</td><td>انتظامی صدر کی طاقت ہے کہ وہ کونسل کے ذریعے منظور شدہ قانون کو ویٹو کرے (کونسل دو تہائی سے زیادہ اکثریت سے ویٹو کو رد کر سکتا ہے)</td></tr><tr><td>انتظامی طاقت عدلیہ کی طاقت کو روکتی ہے</td><td>انتظامی محکمہ عدلیہ کے فیصلوں کے نفاذ کے لیے ذمہ دار ہے، اور عدلیہ کے انتظامی معاملات کا انتظام کرتا ہے</td></tr><tr><td>عدلیہ کی طاقت قانون سازی کی طاقت کو روکتی ہے</td><td>عدالت کی طاقت ہے کہ وہ غیر آئینی جائزہ کرے، اور قانون کو غیر موثر قرار دے</td></tr><tr><td>عدلیہ کی طاقت انتظامی طاقت کو روکتی ہے</td><td>عدالت کی طاقت ہے کہ وہ انتظامی مقدمات کی سماعت کرے، اور انتظامی عمل کی قانونی حیثیت کا جائزہ لے</td></tr><tr><td>نگرانی کی طاقت تین طاقتوں کو روکتی ہے</td><td>نگرانی کمیٹی قانون سازی، انتظامیہ، عدلیہ تین طاقتوں پر مکمل نگرانی کرتی ہے</td></tr><tr><td>تین طاقتیں نگرانی کی طاقت کو روکتی ہیں</td><td>کونسل نگرانی کمیٹی کے ڈائریکٹر کو تقرر کرتا ہے، اور عدالت نگرانی کمیٹی کے غیر قانونی کارروائیوں کی سماعت کرتی ہے</td></tr></tbody></table><h2 id="سابعاً-بنیادی-گورننس-اور-خود-مختاری" tabindex="-1">سابعاً. بنیادی گورننس اور خود مختاری <a class="header-anchor" href="#سابعاً-بنیادی-گورننس-اور-خود-مختاری" aria-label="Permalink to &quot;سابعاً. بنیادی گورننس اور خود مختاری&quot;">​</a></h2><p>مرکزی گورننس کے فریم ورک کے نیچے، بنیادی خود مختاری کا نظام لاگو ہوتا ہے:</p><ul><li><strong>کمیونٹی/گاؤں کی خود مختاری</strong>: بنیادی کمیونٹیز اور گاؤں باشندوں کی خود مختاری کا اطلاق کرتے ہیں، اور باشندوں کی میٹنگ کے ذریعے خود مختاری تنظیم منتخب کرتے ہیں تاکہ مقامی عوامی معاملات چلائے جائیں۔</li><li><strong>位面 کی خود مختاری</strong>: ہر位面 آئین اور قانون کی پیروی کرنے کی شرط پر، مخصوص خود مختاری کے حقدار ہے، اور مقامی صورتحال کے مطابق نفاذ کے تفصیلی قواعد بنا سکتا ہے۔</li><li><strong>نسل کی خود مختاری</strong>: ہر نسل کے بسے ہوئے علاقوں میں نسل کی خود مختاری تنظیم قائم کی جا سکتی ہے، اور اپنی نسل کے اندرونی معاملات چلائے جا سکتے ہیں، لیکن آئین اور قانون کی خلاف ورزی نہیں کر سکتے۔</li><li><strong>صنعت کی خود مختاری</strong>: ہر صنعت میں صنعت کی انجمنیں قائم کی جا سکتی ہیں، اور صنعت کی خود نظم و ضبط اور صنعت کا انتظام کیا جا سکتا ہے۔</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>گورننس کا فریم ورک اور طاقتوں کا توازن اینکر سمبیوسس تہذیب کی طویل مدتی استحکام اور سلامتی کی ادارہ جاتی تحفظ ہے۔ &quot;تین طاقتوں کی تقسیم، چار طاقتوں کا توازن&quot; کے ساختی ڈیزائن، تمام نسلوں کی شرکت کے نمائندہ نظام، اور بنیادی خود مختاری کے گورننس ماڈل کے ذریعے، یہ یقینی بناتا ہے کہ طاقت سورج کی روشنی میں چلے، طاقت کے ارتکاز اور لوٹ مار کے گورننس کی دوبارہ پیدا ہونے کو روکے، اور تمام نسلوں کی مشترکہ ترقی کے لیے ایک مستحکم، منصفانہ، اور موثر گورننس کا نظام فراہم کرے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>40-共生宪法总纲 (سمبیوسس آئین کے بنیادی اصول)</li><li>48-司法体系与裁决机制 (عدلیہ کا نظام اور فیصلے کا طریقہ کار)</li><li>03-共生文明宪章 (سمبیوسس تہذیب کا چارٹر)</li><li>36-社会结构与阶层流动 (سماجی ساخت اور طبقات کی منتقلی)</li></ul>',45)])])}const c=r(o,[["render",i]]);export{b as __pageData,c as default};
